WITH calendario AS (SELECT DISTINCT CAST(fecha_dia AS VARCHAR(10)) AS fecha_saldo FROM pr_bsf_4con.productos_parametria_ft_calendario_saldo WHERE fecha_proceso = '$FECHA_PROCESO' UNION ALL SELECT CAST(CASE WHEN dayofweek(CAST(from_unixtime(unix_timestamp('$FECHA_PROCESO', 'yyyyMMdd'), 'yyyy-MM-dd') AS DATE)) = 2 THEN date_sub(CAST(from_unixtime(unix_timestamp('$FECHA_PROCESO', 'yyyyMMdd'), 'yyyy-MM-dd') AS DATE), 3) ELSE date_sub(CAST(from_unixtime(unix_timestamp('$FECHA_PROCESO', 'yyyyMMdd'), 'yyyy-MM-dd') AS DATE), 1) END AS VARCHAR(10)) AS fecha_saldo FROM (SELECT 1) dummy LEFT JOIN pr_bsf_4con.productos_parametria_ft_calendario_saldo t ON t.fecha_proceso = '$FECHA_PROCESO' WHERE t.fecha_proceso IS NULL ), caja_ahorro AS (SELECT *, RANK() OVER(PARTITION BY nro_cta, id_sucursal, id_cta ORDER BY cbu DESC) AS sort_id FROM pr_bsf_4con.productos_caja_ahorro_dim_maestro WHERE cast(fecha_saldo AS VARCHAR(10)) = (SELECT fecha_saldo FROM calendario) ), cahis AS (SELECT mh.id_sucursal, mh.id_cta id_cuenta, mh.nro_cta nro_cuenta, mh.id_movimiento codigo_movimiento, mh.mto_transaccion, CASE WHEN CAST(mh.id_movimiento AS INT) < 250 THEN mh.mto_transaccion * (-1) WHEN CAST(mh.id_movimiento AS INT) > 749 THEN mh.mto_transaccion * (-1) ELSE mh.mto_transaccion END valor_a_sumarizar, mh.fecha_origen, mh.fecha_ingreso, mh.fecha_valor, rank() OVER (PARTITION BY mh.id_sucursal, mh.id_cta, mh.nro_cta, mh.id_movimiento ORDER BY mh.fecha_valor DESC) ranking FROM pr_bsf_4con.productos_caja_de_ahorro_ft_maestro_historico mh WHERE mh.fecha_ingreso > mh.fecha_valor ), ajus_cap AS (SELECT DISTINCT id_sucursal, nro_cta, id_cta, mto_transaccion FROM pr_bsf_4con.productos_caja_de_ahorro_ft_maestro_historico WHERE id_movimiento = 278 AND id_cta IN (94, 6) AND fecha_valor = date_sub(cast(from_unixtime(unix_timestamp('$FECHA_PROCESO', 'yyyyMMdd'), 'yyyy-MM-dd') AS DATE), 1) ), t1 AS (SELECT cahis.id_sucursal, CAST(cahis.nro_cuenta AS STRING) nro_cuenta, cahis.id_cuenta, cahis.fecha_valor, sum(cahis.valor_a_sumarizar) sumarizado FROM cahis WHERE cahis.ranking = 1 GROUP BY cahis.id_sucursal, cahis.nro_cuenta, cahis.id_cuenta, cahis.fecha_valor), FINAL AS (SELECT CONCAT(camov.nro_cta) nro_cuenta, LPAD(TRIM(CAST(camov.id_cliente_core AS STRING)), 13, '0') AS id_cliente_core, CONCAT('1$FINANCIAL_ID', '0002', lpad(CAST(camov.id_moneda AS STRING), 3, '0'), lpad(CAST(camov.id_sucursal AS STRING), 5, '0'), lpad(CAST(camov.id_cta AS STRING), 6, '0'), '00000000000000', lpad(CAST(camov.nro_cta AS STRING), 12, '0')) id_cuenta, CAST(calendario.fecha_saldo AS varchar(10)) fecha_saldo, camov.fecha_ult_transaccion fecha_ultima_transaccion, camov.mto_saldo_efec_hoy + (CASE WHEN t1.sumarizado IS NULL THEN 0 ELSE t1.sumarizado END) saldo_capital, t1.sumarizado, camov.intereses_devengados_act interes_devengado, CAST(NULL AS DECIMAL(15, 2)) interes_pagado, camov.mto_tasa_int_acreedor tasa_interes, CASE WHEN dti.tasa_efectiva_mensual IS NULL THEN 0 ELSE dti.tasa_efectiva_mensual END tasa_efectiva_mensual, CASE WHEN dti.tasa_nominal_anual IS NULL THEN 0 ELSE dti.tasa_nominal_anual END tasa_nominal_anual, camov.saldo_acreedor_prom_mes_act saldo_promedio_acreedor_mes_actual, camov.saldo_acreedor_prom_mes_ant saldo_promedio_acreedor_mes_anterior, camov.saldo_acreedor_prom_90_dias saldo_promedio_acreedor_90_dias, inte1.saldo_int_hasta AS interes_diario, movi.mto_transaccion AS ajuste_capital, camov.saldo_acreedor_prom_180_dias saldo_promedio_acreedor_180_dias, CAST(camov.id_cta AS INT) AS id_linea FROM caja_ahorro camov CROSS JOIN calendario LEFT OUTER JOIN t1 ON camov.id_sucursal = t1.id_sucursal AND camov.nro_cta = t1.nro_cuenta AND camov.id_cta = CAST(t1.id_cuenta AS VARCHAR(10)) AND camov.fecha_saldo = t1.fecha_valor LEFT OUTER JOIN pr_bsf_4con.productos_ca_dim_tasas_interes dti ON camov.id_sucursal = dti.id_sucursal AND CAST(camov.id_cta AS VARCHAR(10)) = CAST(dti.id_tipo_cuenta AS VARCHAR(10)) AND camov.nro_cta = CAST(dti.nro_cuenta AS VARCHAR(20)) AND dti.fecha_proceso = '$FECHA_PROCESO' LEFT JOIN ajus_cap movi ON camov.nro_cta = cast(movi.nro_cta AS varchar(19)) AND camov.id_sucursal = movi.id_sucursal AND camov.id_cta = cast(movi.id_cta AS varchar(10)) LEFT JOIN pr_bsf_4con.productos_ca_ft_intereses_devengados inte1 ON camov.nro_cta = cast(inte1.nro_cuenta AS varchar(20)) AND camov.id_sucursal = inte1.id_sucursal AND camov.id_cta = cast(inte1.id_tipo_cuenta AS varchar(10)) AND from_unixtime(unix_timestamp(inte1.fecha_proceso, 'yyyyMMdd'), 'yyyy-MM-dd') = cast(from_unixtime(unix_timestamp('$FECHA_PROCESO', 'yyyyMMdd'), 'yyyy-MM-dd') AS DATE) WHERE sort_id = 1 ) SELECT f.sumarizado, f.nro_cuenta, f.id_cliente_core, f.id_cuenta, f.fecha_saldo, cast(f.fecha_ultima_transaccion AS varchar(10)) fecha_ultima_transaccion, f.saldo_capital, f.interes_devengado, f.interes_pagado, cast(f.tasa_interes AS decimal(19, 6)) tasa_interes, cast(f.tasa_efectiva_mensual AS decimal(19, 6)) tasa_efectiva_mensual, cast(f.tasa_nominal_anual AS decimal(19, 6)) tasa_nominal_anual, f.interes_diario, f.ajuste_capital, f.saldo_promedio_acreedor_mes_actual, f.saldo_promedio_acreedor_mes_anterior, f.saldo_promedio_acreedor_90_dias, f.saldo_promedio_acreedor_180_dias, f.id_linea, '$FECHA_PROCESO' AS fecha_monitor FROM FINAL f